// MsgServer is the server API for Msg service.
type MsgServer interface {
	// CreateVestingSchedule creates a new vesting schedule
	CreateVestingSchedule(context.Context, *MsgCreateVestingSchedule) (*MsgCreateVestingScheduleResponse, error)
	// ReleaseVestedTokens releases vested tokens to beneficiary
	ReleaseVestedTokens(context.Context, *MsgReleaseVestedTokens) (*MsgReleaseVestedTokensResponse, error)
	// RevokeVestingSchedule revokes a vesting schedule
	RevokeVestingSchedule(context.Context, *MsgRevokeVestingSchedule) (*MsgRevokeVestingScheduleResponse, error)
	// SubmitProposal submits a new governance proposal
	SubmitProposal(context.Context, *MsgSubmitProposal) (*MsgSubmitProposalResponse, error)
	// Deposit adds a deposit to a proposal
	Deposit(context.Context, *MsgDeposit) (*MsgDepositResponse, error)
	// Vote casts a vote on a proposal
	Vote(context.Context, *MsgVote) (*MsgVoteResponse, error)
	// VoteWeighted casts a weighted vote on a proposal
	VoteWeighted(context.Context, *MsgVoteWeighted) (*MsgVoteWeightedResponse, error)
	// DelegateVote delegates voting power to another address
	DelegateVote(context.Context, *MsgDelegateVote) (*MsgDelegateVoteResponse, error)
	// UndelegateVote removes vote delegation
	UndelegateVote(context.Context, *MsgUndelegateVote) (*MsgUndelegateVoteResponse, error)
	// ExecuteProposal executes a passed proposal after timelock
	ExecuteProposal(context.Context, *MsgExecuteProposal) (*MsgExecuteProposalResponse, error)
	// RevealSecretVote reveals a secret ballot vote
	RevealSecretVote(context.Context, *MsgRevealSecretVote) (*MsgRevealSecretVoteResponse, error)
	// LockVotingTokens locks tokens for voting power boost
	LockVotingTokens(context.Context, *MsgLockVotingTokens) (*MsgLockVotingTokensResponse, error)
	// UnlockVotingTokens unlocks voting tokens after lock period
	UnlockVotingTokens(context.Context, *MsgUnlockVotingTokens) (*MsgUnlockVotingTokensResponse, error)
	// ProposeTreasurySpend proposes a treasury spend
	ProposeTreasurySpend(context.Context, *MsgProposeTreasurySpend) (*MsgProposeTreasurySpendResponse, error)
	// SignTreasurySpend signs a treasury spend proposal
	SignTreasurySpend(context.Context, *MsgSignTreasurySpend) (*MsgSignTreasurySpendResponse, error)
	// ExecuteTreasurySpend executes an approved treasury spend
	ExecuteTreasurySpend(context.Context, *MsgExecuteTreasurySpend) (*MsgExecuteTreasurySpendResponse, error)
	// UpdateParams updates module parameters (governance only)
	UpdateParams(context.Context, *MsgUpdateParams) (*MsgUpdateParamsResponse, error)
	// AdjustInflationRate manually adjusts inflation rate (governance only)
	AdjustInflationRate(context.Context, *MsgAdjustInflationRate) (*MsgAdjustInflationRateResponse, error)
}

